#include "overlapArea.h"
#include "reproject_slice_c.h"

#if defined(_MSC_VER)
  #define INLINE _inline
#else
  #define INLINE inline
#endif

static INLINE double min_4(const double *ptr)
{
    double retval = ptr[0];
    int i;
    for (i = 1; i < 4; ++i) {
        if (ptr[i] < retval) {
            retval = ptr[i];
        }
    }
    return retval;
}

static INLINE double max_4(const double *ptr)
{
    double retval = ptr[0];
    int i;
    for (i = 1; i < 4; ++i) {
        if (ptr[i] > retval) {
            retval = ptr[i];
        }
    }
    return retval;
}

static INLINE double to_rad(double x)
{
    return x * 0.017453292519943295;
}

// Kernel for overlap computation.
static INLINE void _compute_overlap(double *overlap,
                                    double *area_ratio,
                                    double *ilon,
                                    double *ilat,
                                    double *olon,
                                    double *olat)
{
    overlap[0] = computeOverlap(ilon,ilat,olon,olat,0,1,area_ratio);
}

#define GETPTR2(x,ncols,i,j) (x + (i) * (ncols) + (j))
#define GETPTRILON(x,i,j) (x + (j))

void _reproject_slice_c(int startx, int endx, int starty, int endy, int nx_out, int ny_out,
    double *xp_inout, double *yp_inout, double *xw_in, double *yw_in, double *xw_out, double *yw_out,
    double *array, double *array_new, double *weights,
    int col_in, int col_out, int col_array, int col_new)
{
    int i, j, ii, jj, xmin, xmax, ymin, ymax;
    double ilon[4], ilat[4], olon[4], olat[4], minmax_x[4], minmax_y[4];
    double overlap, area_ratio, original;

    // Main loop.
    for (i = startx; i < endx; ++i) {
        for (j = starty; j < endy; ++j) {
            // For every input pixel we find the position in the output image in
            // pixel coordinates, then use the full range of overlapping output
            // pixels with the exact overlap function.

            minmax_x[0] = *GETPTR2(xp_inout,col_in,j,i);
            minmax_x[1] = *GETPTR2(xp_inout,col_in,j,i + 1);
            minmax_x[2] = *GETPTR2(xp_inout,col_in,j + 1,i + 1);
            minmax_x[3] = *GETPTR2(xp_inout,col_in,j + 1,i);

            minmax_y[0] = *GETPTR2(yp_inout,col_in,j,i);
            minmax_y[1] = *GETPTR2(yp_inout,col_in,j,i + 1);
            minmax_y[2] = *GETPTR2(yp_inout,col_in,j + 1,i + 1);
            minmax_y[3] = *GETPTR2(yp_inout,col_in,j + 1,i);

            xmin = (int)(min_4(minmax_x) + .5);
            xmax = (int)(max_4(minmax_x) + .5);
            ymin = (int)(min_4(minmax_y) + .5);
            ymax = (int)(max_4(minmax_y) + .5);

            // Fill in ilon/ilat.
            ilon[0] = to_rad(*GETPTR2(xw_in,col_in,j+1,i));
            ilon[1] = to_rad(*GETPTR2(xw_in,col_in,j+1,i+1));
            ilon[2] = to_rad(*GETPTR2(xw_in,col_in,j,i+1));
            ilon[3] = to_rad(*GETPTR2(xw_in,col_in,j,i));

            ilat[0] = to_rad(*GETPTR2(yw_in,col_in,j+1,i));
            ilat[1] = to_rad(*GETPTR2(yw_in,col_in,j+1,i+1));
            ilat[2] = to_rad(*GETPTR2(yw_in,col_in,j,i+1));
            ilat[3] = to_rad(*GETPTR2(yw_in,col_in,j,i));

            xmin = xmin > 0 ? xmin : 0;
            xmax = (nx_out-1) < xmax ? (nx_out-1) : xmax;
            ymin = ymin > 0 ? ymin : 0;
            ymax = (ny_out-1) < ymax ? (ny_out-1) : ymax;

            for (ii = xmin; ii < xmax + 1; ++ii) {
                for (jj = ymin; jj < ymax + 1; ++jj) {
                    // Fill out olon/olat.
                    olon[0] = to_rad(*GETPTR2(xw_out,col_out,jj+1,ii));
                    olon[1] = to_rad(*GETPTR2(xw_out,col_out,jj+1,ii+1));
                    olon[2] = to_rad(*GETPTR2(xw_out,col_out,jj,ii+1));
                    olon[3] = to_rad(*GETPTR2(xw_out,col_out,jj,ii));

                    olat[0] = to_rad(*GETPTR2(yw_out,col_out,jj+1,ii));
                    olat[1] = to_rad(*GETPTR2(yw_out,col_out,jj+1,ii+1));
                    olat[2] = to_rad(*GETPTR2(yw_out,col_out,jj,ii+1));
                    olat[3] = to_rad(*GETPTR2(yw_out,col_out,jj,ii));

                    // Compute the overlap.
                    _compute_overlap(&overlap,&area_ratio,ilon,ilat,olon,olat);
                    _compute_overlap(&original,&area_ratio,olon,olat,olon,olat);

                    // Write into array_new and weights.
                    *GETPTR2(array_new,col_new,jj,ii) += *GETPTR2(array,col_array,j,i) *
                                                                     (overlap / original);

                    *GETPTR2(weights,col_new,jj,ii) += (overlap / original);
                }
            }
        }
    }
}

--- overlapArea.c ---
/* Methods to compute pixel overlap areas on the sphere.
 *
 * Originally developed in 2003 / 2004 by John Good.
 */

#include <stdio.h>
#if defined(_MSC_VER)
  #define _USE_MATH_DEFINES
#endif
#include <math.h>
#include "mNaN.h"
#include "overlapArea.h"

// Constants

#define FALSE             0
#define TRUE              1
#define FOREVER           1

#define COLINEAR_SEGMENTS 0
#define ENDPOINT_ONLY     1
#define NORMAL_INTERSECT  2
#define NO_INTERSECTION   3

#define CLOCKWISE         1
#define PARALLEL          0
#define COUNTERCLOCKWISE -1

#define UNKNOWN           0
#define P_IN_Q            1
#define Q_IN_P            2

#if defined(DEBUG_OVERLAP_AREA)
    const int DEBUG = 10;
#else
    const int DEBUG = 0;
#endif

const double DEG_TO_RADIANS = M_PI / 180.;
// sin(x) where x = 5e-4 arcsec or cos(x) when x is within 1e-5 arcsec of 90 degrees
const double TOLERANCE = 4.424e-9;
const int NP = 4;
const int NQ = 4;

typedef struct vec {
  double x;
  double y;
  double z;
} Vec;

// Function prototypes

int DirectionCalculator(Vec *a, Vec *b, Vec *c);
int SegSegIntersect(Vec *a, Vec *b, Vec *c, Vec *d, Vec *e, Vec *f, Vec *p,
                    Vec *q);
int Between(Vec *a, Vec *b, Vec *c);
int Cross(Vec *a, Vec *b, Vec *c);
double Dot(Vec *a, Vec *b);
double Normalize(Vec *a);
void Reverse(Vec *a);
void SaveVertex(Vec *a, Vec *P, Vec *Q, Vec *V, int *nv);
void SaveSharedSeg(Vec *p, Vec *q, Vec *P, Vec *Q, Vec *V, int *nv);

void ComputeIntersection(Vec *P, Vec *Q, Vec *V, int *nv);
void EnsureCounterClockWise(Vec *V);

int UpdateInteriorFlag(Vec *p, int interiorFlag, int pEndpointFromQdir,
                       int qEndpointFromPdir, Vec *P, Vec *Q, Vec *V, int *nv);

int Advance(int i, int *i_advances, int n, int inside, Vec *v, Vec *P, Vec *Q, Vec *V, int *nv);

double Girard(int nv, Vec *V);
void RemoveDups(int *nv, Vec *V);

int printDir(char *point, char *vector, int dir);

/*
 * Sets up the polygons, runs the overlap computation, and returns the area of overlap.
 */
double computeOverlap(double *ilon, double *ilat, double *olon, double *olat,
                      int energyMode, double refArea, double *areaRatio) {
  int i;
  double thisPixelArea;
  Vec P[8], Q[8], V[16];
  int nv;

  *areaRatio = 1.;

  if (energyMode) {
    nv = 0;

    for (i = 0; i < 4; ++i)
      SaveVertex(&P[i], P, Q, V, &nv);

    thisPixelArea = Girard(nv, V);

    *areaRatio = thisPixelArea / refArea;
  }

  nv = 0;

  if (DEBUG >= 4) {
    printf("Input (P):\n");
    for (i = 0; i < 4; ++i)
      printf("%10.6f %10.6f\n", ilon[i], ilat[i]);

    printf("\nOutput (Q):\n");
    for (i = 0; i < 4; ++i)
      printf("%10.6f %10.6f\n", olon[i], olat[i]);

    printf("\n");
    fflush(stdout);
  }

  for (i = 0; i < 4; ++i) {
    P[i].x = cos(ilon[i]) * cos(ilat[i]);
    P[i].y = sin(ilon[i]) * cos(ilat[i]);
    P[i].z = sin(ilat[i]);
  }

  for (i = 0; i < 4; ++i) {
    Q[i].x = cos(olon[i]) * cos(olat[i]);
    Q[i].y = sin(olon[i]) * cos(olat[i]);
    Q[i].z = sin(olat[i]);
  }

  EnsureCounterClockWise(P);
  EnsureCounterClockWise(Q);

  ComputeIntersection(P, Q, V, &nv);

  return (Girard(nv, V));
}

void EnsureCounterClockWise(Vec *V) {

  // Make sure that the polygon is counter-clockwise. For now we assume that we
  // are dealing with convex quadrilaterals, and therefore we can just check
  // the two first sides of the polygon.

  Vec S1, S2, C;
  double dir;
  double tmp;

  S1.x = V[1].x - V[0].x;
  S1.y = V[1].y - V[0].y;
  S1.z = V[1].z - V[0].z;

  S2.x = V[2].x - V[1].x;
  S2.y = V[2].y - V[1].y;
  S2.z = V[2].z - V[1].z;

  Cross(&S1, &S2, &C);

  dir = Dot(&V[1], &C);

  if (dir < 0) {
    tmp = V[2].x;
    V[2].x = V[0].x;
    V[0].x = tmp;
    tmp = V[2].y;
    V[2].y = V[0].y;
    V[0].y = tmp;
    tmp = V[2].z;
    V[2].z = V[0].z;
    V[0].z = tmp;
  }

}

/*
 * Find the polygon defining the area of overlap
 * between the two input polygons P and Q.
 */
void ComputeIntersection(Vec *P, Vec *Q, Vec *V, int *nv) {
  Vec Pdir, Qdir;              // "Current" directed edges on P and Q
  Vec other;                   // Temporary "edge-like" variable
  int ip, iq;                  // Indices of ends of Pdir, Qdir
  int ip_begin, iq_begin;      // Indices of beginning of Pdir, Qdir
  int PToQDir;                 // Qdir direction relative to Pdir
                               // (e.g. CLOCKWISE)
  int qEndpointFromPdir;       // End P vertex as viewed from beginning
                               // of Qdir relative to Qdir
  int pEndpointFromQdir;       // End Q vertex as viewed from beginning
                               // of Pdir relative to Pdir
  Vec firstIntersection;       // Point of intersection of Pdir, Qdir
  Vec secondIntersection;      // Second point of intersection
                               // (if there is one)
  int interiorFlag;            // Which polygon is inside the other
  int contained;               // Used for "completely contained" check
  int p_advances, q_advances;  // Number of times we've advanced
                               // P and Q indices
  int isFirstPoint;            // Is this the first point?
  int intersectionCode;        // SegSegIntersect() return code.

  // Check for Q contained in P

  contained = TRUE;

  for (ip = 0; ip < NP; ++ip) {
    ip_begin = (ip + NP - 1) % NP;

    Cross(&P[ip_begin], &P[ip], &Pdir);
    Normalize(&Pdir);

    for (iq = 0; iq < NQ; ++iq) {
      if (DEBUG >= 4) {
        printf("Q in P: Dot%d%d = %12.5e\n", ip, iq, Dot(&Pdir, &Q[iq]));
        fflush(stdout);
      }

      if (Dot(&Pdir, &Q[iq]) < -TOLERANCE) {
        contained = FALSE;
        break;
      }
    }

    if (!contained)
      break;
  }

  if (contained) {
    if (DEBUG >= 4) {
      printf("Q is entirely contained in P (output pixel is in input pixel)\n");
      fflush(stdout);
    }

    for (iq = 0; iq < NQ; ++iq)
      SaveVertex(&Q[iq], P, Q, V, nv);

    return;
  }

  // Check for P contained in Q

  contained = TRUE;

  for (iq = 0; iq < NQ; ++iq) {
    iq_begin = (iq + NQ - 1) % NQ;

    Cross(&Q[iq_begin], &Q[iq], &Qdir);
    Normalize(&Qdir);

    for (ip = 0; ip < NP; ++ip) {
      if (DEBUG >= 4) {
        printf("P in Q: Dot%d%d = %12.5e\n", iq, ip, Dot(&Qdir, &P[ip]));
        fflush(stdout);
      }

      if (Dot(&Qdir, &P[ip]) < -TOLERANCE) {
        contained = FALSE;
        break;
      }
    }

    if (!contained)
      break;
  }

  if (contained) {
    if (DEBUG >= 4) {
      printf("P is entirely contained in Q (input pixel is in output pixel)\n");
      fflush(stdout);
    }

    *nv = 0;
    for (ip = 0; ip < NP; ++ip)
      SaveVertex(&P[ip], P, Q, V, nv);

    return;
  }

  // Then check for polygon overlap

  ip = 0;
  iq = 0;

  p_advances = 0;
  q_advances = 0;

  interiorFlag = UNKNOWN;
  isFirstPoint = TRUE;

  while (FOREVER) {
    if (p_advances >= 2 * NP)
      break;
    if (q_advances >= 2 * NQ)
      break;
    if (p_advances >= NP && q_advances >= NQ)
      break;

    if (DEBUG >= 4) {
      printf("-----\n");

      if (interiorFlag == UNKNOWN) {
        printf("Before advances (UNKNOWN interiorFlag): ip=%d, iq=%d ", ip, iq);
        printf("(p_advances=%d, q_advances=%d)\n", p_advances, q_advances);
      }

      else if (interiorFlag == P_IN_Q) {
        printf("Before advances (P_IN_Q): ip=%d, iq=%d ", ip, iq);
        printf("(p_advances=%d, q_advances=%d)\n", p_advances, q_advances);
      }

      else if (interiorFlag == Q_IN_P) {
        printf("Before advances (Q_IN_P): ip=%d, iq=%d ", ip, iq);
        printf("(p_advances=%d, q_advances=%d)\n", p_advances, q_advances);
      } else
        printf("\nBAD INTERIOR FLAG.  Shouldn't get here\n");

      fflush(stdout);
    }

    // Previous point in the polygon

    ip_begin = (ip + NP - 1) % NP;
    iq_begin = (iq + NQ - 1) % NQ;

    // The current polygon edges are given by
    // the cross product of the vertex vectors

    Cross(&P[ip_begin], &P[ip], &Pdir);
    Cross(&Q[iq_begin], &Q[iq], &Qdir);

    PToQDir = DirectionCalculator(&P[ip], &Pdir, &Qdir);

    Cross(&Q[iq_begin], &P[ip], &other);
    pEndpointFromQdir = DirectionCalculator(&Q[iq_begin], &Qdir, &other);

    Cross(&P[ip_begin], &Q[iq], &other);
    qEndpointFromPdir = DirectionCalculator(&P[ip_begin], &Pdir, &other);

    if (DEBUG >= 4) {
      printf("   ");
      printDir("P", "Q", PToQDir);
      printDir("pEndpoint", "Q", pEndpointFromQdir);
      printDir("qEndpoint", "P", qEndpointFromPdir);
      printf("\n");
      fflush(stdout);
    }

    // Find point(s) of intersection between edges

    intersectionCode = SegSegIntersect(&Pdir, &Qdir, &P[ip_begin], &P[ip],
                                       &Q[iq_begin], &Q[iq], &firstIntersection,
                                       &secondIntersection);

    if (intersectionCode == NORMAL_INTERSECT
        || intersectionCode == ENDPOINT_ONLY) {
      if (interiorFlag == UNKNOWN && isFirstPoint) {
        p_advances = 0;
        q_advances = 0;

        isFirstPoint = FALSE;
      }

      interiorFlag = UpdateInteriorFlag(&firstIntersection, interiorFlag,
                                        pEndpointFromQdir, qEndpointFromPdir, P, Q, V, nv);

      if (DEBUG >= 4) {
        if (interiorFlag == UNKNOWN)
          printf("   interiorFlag -> UNKNOWN\n");

        else if (interiorFlag == P_IN_Q)
          printf("   interiorFlag -> P_IN_Q\n");

        else if (interiorFlag == Q_IN_P)
          printf("   interiorFlag -> Q_IN_P\n");

        else
          printf("   BAD interiorFlag.  Shouldn't get here\n");

        fflush(stdout);
      }
    }

    // Advance rules

    // Special case: Pdir & Qdir overlap and oppositely oriented.

    if ((intersectionCode == COLINEAR_SEGMENTS) && (Dot(&Pdir, &Qdir) < 0)) {
      if (DEBUG >= 4) {
        printf("   ADVANCE: Pdir and Qdir are colinear.\n");
        fflush(stdout);
      }

      SaveSharedSeg(&firstIntersection, &secondIntersection, P, Q, V, nv);

      RemoveDups(nv, V);
      return;
    }

    // Special case: Pdir & Qdir parallel and separated.

    if ((PToQDir == PARALLEL) && (pEndpointFromQdir == CLOCKWISE)
        && (qEndpointFromPdir == CLOCKWISE)) {
      if (DEBUG >= 4) {
        printf("   ADVANCE: Pdir and Qdir are disjoint.\n");
        fflush(stdout);
      }

      RemoveDups(nv, V);
      return;
    }

    // Special case: Pdir & Qdir colinear.

    else if ((PToQDir == PARALLEL) && (pEndpointFromQdir == PARALLEL)
        && (qEndpointFromPdir == PARALLEL)) {
      if (DEBUG >= 4) {
        printf("   ADVANCE: Pdir and Qdir are colinear.\n");
        fflush(stdout);
      }

      // Advance but do not output point.

      if (interiorFlag == P_IN_Q)
        iq = Advance(iq, &q_advances, NQ, interiorFlag == Q_IN_P, &Q[iq], P, Q, V, nv);
      else
        ip = Advance(ip, &p_advances, NP, interiorFlag == P_IN_Q, &P[ip], P, Q, V, nv);

--- overlapAreaPP.c ---
/* Methods to compute pixel overlap areas in the plane.
 *
 * Originally developed in 2003 / 2004 by John Good.
 */

#include <math.h>

double computeOverlapPP(double *ix, double *iy, double minX, double maxX,
                        double minY, double maxY, double pixelArea);

double polyArea(int npts, double *nx, double *ny);

int rectClip(int n, double *x, double *y, double *nx, double *ny, double minX,
             double minY, double maxX, double maxY);
int lineClip(int n, double *x, double *y, double *nx, double *ny, double val,
             int dir);
int inPlane(double test, double divider, int direction);
int ptInPoly(double x, double y, int n, double *xp, double *yp);

// Global variables
double tmpX0[100];
double tmpX1[100];
double tmpY0[100];
double tmpY1[100];

/*
 * Sets up the polygons, runs the overlap
 * computation, and returns the area of overlap.
 * This version works in pixel space rather than
 * on the celestial sphere.
 */
double computeOverlapPP(double *ix, double *iy, double minX, double maxX,
                        double minY, double maxY, double pixelArea) {
  int npts;
  double area;

  double nx[100];
  double ny[100];

  double xp[4], yp[4];

  // Clip the input pixel polygon with the output pixel range

  npts = rectClip(4, ix, iy, nx, ny, minX, minY, maxX, maxY);

  // If no points, it may mean that the output is
  // completely contained in the input

  if (npts < 3) {
    xp[0] = minX;
    yp[0] = minY;
    xp[1] = maxX;
    yp[1] = minY;
    xp[2] = maxX;
    yp[2] = maxY;
    xp[3] = minX;
    yp[3] = maxY;

    if (ptInPoly(ix[0], iy[0], 4, xp, yp)) {
      area = pixelArea;
      return area;
    }

    return 0.;
  }

  area = polyArea(npts, nx, ny) * pixelArea;

  return area;
}

int rectClip(int n, double *x, double *y, double *nx, double *ny, double minX,
             double minY, double maxX, double maxY) {
  int nCurr;

  nCurr = lineClip(n, x, y, tmpX0, tmpY0, minX, 1);

  if (nCurr > 0) {
    nCurr = lineClip(nCurr, tmpX0, tmpY0, tmpX1, tmpY1, maxX, 0);

    if (nCurr > 0) {
      nCurr = lineClip(nCurr, tmpY1, tmpX1, tmpY0, tmpX0, minY, 1);

      if (nCurr > 0) {
        nCurr = lineClip(nCurr, tmpY0, tmpX0, ny, nx, maxY, 0);
      }
    }
  }

  return nCurr;
}

int lineClip(int n, double *x, double *y, double *nx, double *ny, double val,
             int dir) {
  int i;
  int nout;
  int last;

  double ycross;

  nout = 0;
  last = inPlane(x[n - 1], val, dir);

  for (i = 0; i < n; ++i) {
    if (last) {
      if (inPlane(x[i], val, dir)) {
        // Both endpoints in, just add the new point

        nx[nout] = x[i];
        ny[nout] = y[i];

        ++nout;
      } else {
        // Moved out of the clip region, add the point we moved out

        if (i == 0)
          ycross = y[n - 1]
              + (y[0] - y[n - 1]) * (val - x[n - 1]) / (x[0] - x[n - 1]);
        else
          ycross = y[i - 1]
              + (y[i] - y[i - 1]) * (val - x[i - 1]) / (x[i] - x[i - 1]);

        nx[nout] = val;
        ny[nout] = ycross;

        ++nout;

        last = 0;
      }
    } else {
      if (inPlane(x[i], val, dir)) {
        // Moved into the clip region.
        // Add the point we moved in, and the end point.

        if (i == 0)
          ycross = y[n - 1]
              + (y[0] - y[n - 1]) * (val - x[n - 1]) / (x[i] - x[n - 1]);
        else
          ycross = y[i - 1]
              + (y[i] - y[i - 1]) * (val - x[i - 1]) / (x[i] - x[i - 1]);

        nx[nout] = val;
        ny[nout] = ycross;

        ++nout;

        nx[nout] = x[i];
        ny[nout] = y[i];

        ++nout;

        last = 1;
      } else {
        // Segment entirely clipped.
      }
    }
  }

  return nout;
}

int inPlane(double test, double divider, int direction) {
  if (direction)
    return test >= divider;
  else
    return test <= divider;
}

double polyArea(int npts, double *nx, double *ny) {
  int i, inext;
  double area;

  area = 0.;

  for (i = 0; i < npts; ++i) {
    inext = (i + 1) % npts;

    area += nx[i] * ny[inext] - nx[inext] * ny[i];
  }

  area = fabs(area) / 2;

  return area;
}

int ptInPoly(double x, double y, int n, double *xp, double *yp) {
  int i, inext, count;
  double t;

  count = 0;

  for (i = 0; i < n; ++i) {
    inext = (i + 1) % n;

    if (((yp[i] <= y) && (yp[inext] > y))
        || ((yp[i] > y) && (yp[inext] <= y))) {
      t = (y - yp[i]) / (yp[inext] - yp[i]);

      if (x < xp[i] + t * (xp[inext] - xp[i]))
        ++count;
    }
  }

  return (count & 1);
}

