/* Small-pixel spherical intersection helpers. */
double Dot2(const double *a, const double *b);
double Cross2(const double *a, const double *b, const double *c);
int GnomonicOverlap(Vec *P, Vec *Q, double *area);

typedef struct point2 {
  double x;
  double y;
} Point2;

static double cross2(Point2 *a, Point2 *b, Point2 *c) {
  return (b->x - a->x) * (c->y - a->y)
       - (b->y - a->y) * (c->x - a->x);
}

static int clip_edge(Point2 *in, int nin, Point2 *out, Point2 *a, Point2 *b) {
  int i, nout = 0;
  Point2 p, q, x;
  double dp, dq, t;
  int pin, qin;

  if (nin == 0)
    return 0;

  for (i = 0; i < nin; ++i) {
    p = in[i];
    q = in[(i + 1) % nin];
    dp = cross2(a, b, &p);
    dq = cross2(a, b, &q);
    pin = dp >= -1.e-14;
    qin = dq >= -1.e-14;

    if (pin)
      out[nout++] = p;

    if (pin != qin) {
      t = dp / (dp - dq);
      x.x = p.x + t * (q.x - p.x);
      x.y = p.y + t * (q.y - p.y);
      out[nout++] = x;
    }
  }

  return nout;
}

static double triangle_area(Vec *a, Vec *b, Vec *c) {
  Vec cross;
  double numerator;
  double denominator;

  Cross(b, c, &cross);
  numerator = fabs(Dot(a, &cross));
  denominator = 1. + Dot(a, b) + Dot(b, c) + Dot(c, a);
  return 2. * atan2(numerator, denominator);
}

/* Compute overlap in a gnomonic tangent plane, where spherical great-circle
 * edges become straight lines.  This is used for the small polygons typical
 * of celestial image pixels; it avoids cancellation in the old edge walker. */
int GnomonicOverlap(Vec *P, Vec *Q, double *area) {
  Vec center, ref, e1, e2;
  Point2 pp[4], qq[4], work[16], next[16], vertex;
  int i, n, qn;
  double center_length, denom, signed_q_area;

  center.x = center.y = center.z = 0.;
  for (i = 0; i < 4; ++i) {
    center.x += P[i].x + Q[i].x;
    center.y += P[i].y + Q[i].y;
    center.z += P[i].z + Q[i].z;
  }
  center_length = Normalize(&center);
  if (center_length == 0.)
    return 0;

  /* A gnomonic chart only covers one hemisphere. */
  for (i = 0; i < 4; ++i) {
    if (Dot(&center, &P[i]) <= 0.05 || Dot(&center, &Q[i]) <= 0.05)
      return 0;
  }

  if (fabs(center.z) < 0.9) {
    ref.x = 0.; ref.y = 0.; ref.z = 1.;
  } else {
    ref.x = 0.; ref.y = 1.; ref.z = 0.;
  }
  Cross(&ref, &center, &e1);
  Normalize(&e1);
  Cross(&center, &e1, &e2);
  Normalize(&e2);

  for (i = 0; i < 4; ++i) {
    denom = Dot(&P[i], &center);
    pp[i].x = Dot(&P[i], &e1) / denom;
    pp[i].y = Dot(&P[i], &e2) / denom;
    denom = Dot(&Q[i], &center);
    qq[i].x = Dot(&Q[i], &e1) / denom;
    qq[i].y = Dot(&Q[i], &e2) / denom;
  }

  signed_q_area = 0.;
  for (i = 0; i < 4; ++i)
    signed_q_area += qq[i].x * qq[(i + 1) % 4].y
                   - qq[(i + 1) % 4].x * qq[i].y;
  if (signed_q_area < 0.) {
    for (i = 0; i < 2; ++i) {
      Point2 tmp = qq[i];
      qq[i] = qq[3 - i];
      qq[3 - i] = tmp;
    }
  }

  n = 4;
  for (i = 0; i < 4; ++i)
    work[i] = pp[i];
  for (i = 0; i < 4; ++i) {
    n = clip_edge(work, n, next, &qq[i], &qq[(i + 1) % 4]);
    for (qn = 0; qn < n; ++qn)
      work[qn] = next[qn];
    if (n < 3) {
      *area = 0.;
      return 1;
    }
  }

  *area = 0.;
  for (i = 1; i < n - 1; ++i) {
    Vec a, b, c;
    vertex.x = work[0].x;
    vertex.y = work[0].y;
    a.x = center.x + vertex.x * e1.x + vertex.y * e2.x;
    a.y = center.y + vertex.x * e1.y + vertex.y * e2.y;
    a.z = center.z + vertex.x * e1.z + vertex.y * e2.z;
    Normalize(&a);

    vertex.x = work[i].x;
    vertex.y = work[i].y;
    b.x = center.x + vertex.x * e1.x + vertex.y * e2.x;
    b.y = center.y + vertex.x * e1.y + vertex.y * e2.y;
    b.z = center.z + vertex.x * e1.z + vertex.y * e2.z;
    Normalize(&b);

    vertex.x = work[i + 1].x;
    vertex.y = work[i + 1].y;
    c.x = center.x + vertex.x * e1.x + vertex.y * e2.x;
    c.y = center.y + vertex.x * e1.y + vertex.y * e2.y;
    c.z = center.z + vertex.x * e1.z + vertex.y * e2.z;
    Normalize(&c);

    *area += triangle_area(&a, &b, &c);
  }

  return 1;
}

