290	    P[i].y = sin(ilon[i]) * cos(ilat[i]);
291	    P[i].z = sin(ilat[i]);
292	  }
293	
294	  for (i = 0; i < 4; ++i) {
295	    Q[i].x = cos(olon[i]) * cos(olat[i]);
296	    Q[i].y = sin(olon[i]) * cos(olat[i]);
297	    Q[i].z = sin(olat[i]);
298	  }
299	
300	  /* For polygons within one hemisphere, gnomonic projection maps great
301	   * circles to straight lines.  Clipping in that plane avoids the severe
302	   * loss of precision in cross/dot products when adjacent sky vertices are
303	   * separated by only a few micro-radians. */
304	  if (!energyMode && GnomonicOverlap(P, Q, &thisPixelArea))
305	    return thisPixelArea;
306	
307	  EnsureCounterClockWise(P);
308	  EnsureCounterClockWise(Q);
309	
310	  ComputeIntersection(P, Q, V, &nv);
311	
312	  return (Girard(nv, V));
313	}
