315	void EnsureCounterClockWise(Vec *V) {
316	
317	  // Make sure that the polygon is counter-clockwise. For now we assume that we
318	  // are dealing with convex quadrilaterals, and therefore we can just check
319	  // the two first sides of the polygon.
320	
321	  Vec S1, S2, C;
322	  double dir;
323	  double tmp;
324	
325	  S1.x = V[1].x - V[0].x;
326	  S1.y = V[1].y - V[0].y;
327	  S1.z = V[1].z - V[0].z;
328	
329	  S2.x = V[2].x - V[1].x;
330	  S2.y = V[2].y - V[1].y;
